# compare_confirmatory_baselines.R -- field-by-field comparison of the package-side
# confirmatory output (scenarios C01-C12) across three files:
#
#   NEW   conf_package.json in this folder, as regenerated by conf_R_01_package.R
#         in the current run_all pipeline (dtasamplesize 0.7.0).
#   V069  historical_not_current/conf_package_38f12a8_v0.6.9.json: the file in
#         commit 38f12a8 (dtasamplesize 0.6.9, 2026-10-06).
#   RE063 historical_not_current/conf_package_bc943e0_rerun_2026-09-16_v0.6.3.json:
#         the file in commit bc943e0, the re-run of 2026-09-16 with 0.6.3.
#
# Why this script exists: conf_R_07_reverify_version.R compares the installed
# package with conf_package.json, but in the run_all pipeline conf_R_01 has just
# rewritten that file with the same package, so that comparison is between an
# output and its own regeneration. This script compares the regenerated file with
# the two earlier files kept in the repository history.
#
# What it does: for every field the files have in common (N_total, joint_assurance,
# mcse, assurance_method, max_assurance_evaluated, N_at_max_assurance, the warning
# texts, and N and assurance at N-1, N and N+1) it prints identical() and, for
# numeric fields, the absolute difference; for each field that is not identical it
# prints both values. Fields present in only one of the files are listed
# separately. The script describes differences; it does not label them as
# acceptable or not. Timings (`secs`) are listed but are not results.
#
# Usage:  Rscript validation/python/compare_confirmatory_baselines.R
#         (from any directory; paths are resolved from the script's own location)
# Output: console only. run_all.sh and run_all.ps1 send it to
#         logs/compare_confirmatory_baselines.R.log
# Needs:  jsonlite. No dtasamplesize call.

suppressPackageStartupMessages(library(jsonlite))

script_dir <- local({
  a <- commandArgs(FALSE)
  f <- sub("^--file=", "", a[grepl("^--file=", a)])
  if (length(f) == 1) dirname(normalizePath(f, winslash = "/")) else normalizePath(getwd(), winslash = "/")
})

files <- c(
  NEW   = file.path(script_dir, "conf_package.json"),
  V069  = file.path(script_dir, "historical_not_current", "conf_package_38f12a8_v0.6.9.json"),
  RE063 = file.path(script_dir, "historical_not_current", "conf_package_bc943e0_rerun_2026-09-16_v0.6.3.json")
)
labels <- c(
  NEW   = "regenerated in the current run (dtasamplesize 0.7.0)",
  V069  = "commit 38f12a8 (dtasamplesize 0.6.9)",
  RE063 = "commit bc943e0, re-run of 2026-09-16 with 0.6.3"
)

cat("compare_confirmatory_baselines.R\n")
cat("R:", R.version.string, "\n")
cat("jsonlite:", as.character(packageVersion("jsonlite")), "\n\n")
cat("Files compared:\n")
for (k in names(files)) {
  if (!file.exists(files[[k]])) stop("missing file: ", files[[k]])
  cat(sprintf("  %-6s %s\n         %s\n         sha256 %s\n", k, labels[[k]], files[[k]],
              unname(tools::sha256sum(files[[k]]))))
}
conf_log <- file.path(script_dir, "logs", "conf_R_01_package.R.log")
if (file.exists(conf_log)) {
  ll <- readLines(conf_log, warn = FALSE)
  cat("\nLine of logs/conf_R_01_package.R.log that states the package used for NEW:\n  ",
      paste(grep("^dtasamplesize:", ll, value = TRUE), collapse = " | "), "\n", sep = "")
}

# Flatten a parsed scenario list to a named list of leaf values. NULL (JSON null)
# becomes NA; a vector of strings (warnings) is kept as one character vector.
flatten <- function(x, prefix = "") {
  if (is.list(x) && length(x) > 0 && !is.null(names(x))) {
    out <- list()
    for (nm in names(x)) out <- c(out, flatten(x[[nm]], if (nzchar(prefix)) paste(prefix, nm, sep = ".") else nm))
    out
  } else if (is.list(x)) {                      # unnamed list: a vector of warnings, or empty
    v <- unlist(x, use.names = FALSE)
    setNames(list(if (is.null(v)) character(0) else v), prefix)
  } else if (is.null(x)) {
    setNames(list(NA), prefix)
  } else {
    setNames(list(x), prefix)
  }
}
read_flat <- function(path) {
  d <- fromJSON(path, simplifyVector = FALSE)
  out <- list()
  for (id in names(d)) out <- c(out, flatten(d[[id]], id))
  out
}
flat <- lapply(files, read_flat)
scen <- sprintf("C%02d", 1:12)

show <- function(v) {
  if (length(v) == 0) return("<empty>")
  if (is.character(v)) return(paste0("\"", substr(v, 1, 110), if (any(nchar(v) > 110)) "..." else "", "\"", collapse = " | "))
  if (is.numeric(v)) return(format(v, digits = 17))
  paste(format(v), collapse = ", ")
}
leaf_of <- function(path) sub("^C[0-9]+\\.", "", path)

compare_pair <- function(a, b) {
  fa <- flat[[a]]; fb <- flat[[b]]
  cat(strrep("=", 78), "\n", sep = "")
  cat(sprintf("%s (%s)\n  versus\n%s (%s)\n", a, labels[[a]], b, labels[[b]]))
  cat(strrep("=", 78), "\n", sep = "")
  common <- intersect(names(fa), names(fb))
  only_a <- setdiff(names(fa), names(fb)); only_b <- setdiff(names(fb), names(fa))
  rows <- list()
  for (p in common) {
    va <- fa[[p]]; vb <- fb[[p]]
    ident <- identical(va, vb)
    num <- is.numeric(va) && is.numeric(vb) && length(va) == 1 && length(vb) == 1
    d <- if (num && !is.na(va) && !is.na(vb)) abs(va - vb) else NA_real_
    rows[[length(rows) + 1L]] <- data.frame(path = p, scenario = sub("\\..*$", "", p), leaf = leaf_of(p),
                                            identical = ident, absdiff = d, stringsAsFactors = FALSE)
  }
  tab <- do.call(rbind, rows)
  is_time <- tab$leaf == "secs"
  cat(sprintf("\nFields in common: %d (of which %d are timings, listed but not results).\n", nrow(tab), sum(is_time)))
  cat(sprintf("Identical: %d; not identical: %d (timings excluded: %d identical, %d not identical).\n",
              sum(tab$identical), sum(!tab$identical),
              sum(tab$identical & !is_time), sum(!tab$identical & !is_time)))

  cat("\nPer scenario, number of non-identical result fields (timings excluded):\n")
  for (s in scen) {
    t <- tab[tab$scenario == s & !is_time, ]
    cat(sprintf("  %s  fields %2d  not identical %2d  max absolute difference over numeric fields: %s\n", s, nrow(t),
                sum(!t$identical),
                if (all(is.na(t$absdiff))) "n/a" else format(max(t$absdiff, na.rm = TRUE), digits = 6)))
  }

  cat("\nMaximum absolute difference by field (numeric fields present as numbers in both files):\n")
  for (lf in unique(tab$leaf[!is_time])) {
    t <- tab[tab$leaf == lf & !is.na(tab$absdiff), ]
    if (nrow(t) == 0) next
    cat(sprintf("  %-40s n = %2d  max |diff| = %-12s  scenarios not identical: %s\n", lf, nrow(t),
                format(max(t$absdiff), digits = 6),
                { w <- t$scenario[!t$identical]; if (length(w)) paste(w, collapse = " ") else "none" }))
  }

  nd <- tab[!tab$identical & !is_time, ]
  cat(sprintf("\nFields that are not identical (%d), with both values:\n", nrow(nd)))
  for (i in seq_len(nrow(nd))) {
    p <- nd$path[i]
    cat(sprintf("  %-34s %s = %s\n  %-34s %s = %s%s\n", p, a, show(fa[[p]]), "", b, show(fb[[p]]),
                if (is.na(nd$absdiff[i])) "" else sprintf("   (absolute difference %s)", format(nd$absdiff[i], digits = 6))))
  }
  cat(sprintf("\nTimings (secs), for reference only: %s\n",
              paste(sprintf("%s %s/%s", tab$scenario[is_time], format(round(unlist(lapply(tab$path[is_time], function(p) fa[[p]])), 1)),
                            format(round(unlist(lapply(tab$path[is_time], function(p) fb[[p]])), 1))), collapse = "; ")))

  cat(sprintf("\nFields only in %s (%d):\n", a, length(only_a)))
  for (p in only_a) cat(sprintf("  %-34s = %s\n", p, show(fa[[p]])))
  cat(sprintf("Fields only in %s (%d):\n", b, length(only_b)))
  for (p in only_b) cat(sprintf("  %-34s = %s\n", p, show(fb[[p]])))
  cat("\n")
  invisible(tab)
}

compare_pair("NEW", "V069")
compare_pair("NEW", "RE063")
compare_pair("V069", "RE063")

cat("End of comparison. The script reports differences; it does not judge them.\n")
